import { StaggeredMenu } from "solen-design/react";

const items = [
  { label: "Home", link: "#", ariaLabel: "Home" },
  { label: "Work", link: "#", ariaLabel: "Work" },
  { label: "About", link: "#", ariaLabel: "About" },
  { label: "Contact", link: "#", ariaLabel: "Contact" }
];

const socials = [
  { label: "Email", link: "#" },
  { label: "Blog", link: "#" }
];

<StaggeredMenu
  position="right"
  items={items}
  socialItems={socials}
  colors={["#B497CF", "#5227FF"]}
  accentColor="#5227FF"
  menuButtonColor="#fff"
  openMenuButtonColor="#fff"
  displayItemNumbering={true}
  displaySocials={true}
  changeMenuColorOnOpen={true}
  closeOnClickAway={true}
  onMenuOpen={() => console.log("open")}
  onMenuClose={() => console.log("close")}
/>
